DO $$
BEGIN
 IF to_regclass('private.admission_control') IS NULL OR to_regclass('private.admission_requests') IS NULL THEN RAISE EXCEPTION 'missing_admission_state'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_db_role_setting s CROSS JOIN LATERAL unnest(s.setconfig) x WHERE s.setrole=(SELECT oid FROM pg_roles WHERE rolname='authenticator') AND s.setdatabase=(SELECT oid FROM pg_database WHERE datname=current_database()) AND x='pgrst.db_pre_request=public.admission_enforce') THEN RAISE EXCEPTION 'missing_admission_request_fence'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname='public' OR (n.nspname='realtime' AND c.relname='messages')) AND c.relkind IN ('r','p') AND c.relrowsecurity AND (has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_any_column_privilege('anon',c.oid,'SELECT,INSERT,UPDATE') OR has_any_column_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE')) AND NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='product_admission_fence' AND NOT p.polpermissive)) THEN RAISE EXCEPTION 'missing_admission_rls_fence'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtname='product_admission_new_table_fence' AND evtenabled<>'D') THEN RAISE EXCEPTION 'missing_admission_future_table_fence'; END IF;
 IF has_function_privilege('authenticated','public.admin_admission_mutate(uuid,text,text[],text,uuid)','EXECUTE') OR has_function_privilege('anon','public.admin_admission_page(uuid,text,text,integer)','EXECUTE') OR has_function_privilege('authenticated','public.admission_check_user(uuid)','EXECUTE') THEN RAISE EXCEPTION 'overbroad_admission_permissions'; END IF;
END $$;
